        pool = new Pool({
            connectionString,
            max: 20,
            connectionTimeoutMillis: 5000,
            idleTimeoutMillis: 30000
        });

        pool.on('error', (err) => {
            node.error("Unexpected DB pool error", err);
            return null;
        });

        pool.on('connect', () => {
            // node.warn("DB connected");
        });

        await pool.query("SELECT NOW()");

        flow.set('pg_pool', pool);
        node.warn("PostgreSQL pool created successfully");
    } catch (err) {
        node.error("Failed to create PostgreSQL pool", err);
        return null;
    }
};

