const splitIntoChunks = (text, limit) => {
    if (text.length <= limit) return [text];

    const chunks = [];
    let currentChunk = "";
    const lines = text.split('\n');

    for (const line of lines) {
        if ((currentChunk + line).length > limit) {
            chunks.push(currentChunk.trim());
            currentChunk = line + "\n";
        } else {
