    msg.payload = {
        status: 'error',
        message: msg.error?.message || 'Database error occurred',
        data: null
    };

    return msg;
}

if (!msg.payload || msg.payload.length === 0) {
    msg.statusCode = 404;
    msg.payload = {
        status: 'error',
        message: 'Report not found',
        data: null
    };

    return msg;
}

msg.statusCode = 200;
msg.payload = {
    status: 'success',
    message: null,
    data: msg.payload?.[0] || {}
};

return msg;

const error = msg.error || {};
const source = error.source || {};

// Форматуємо дату та час
const timestamp = new Date().toLocaleString('es-ES', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    timeZone: 'Europe/Madrid'
}).replaceAll('/', '.');

let payloadSnippet = "No payload data";
if (msg.payload !== undefined) {
    try {
        const jsonString = JSON.stringify(msg.payload, null, 2) || "";
        payloadSnippet = jsonString
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;');

        if (payloadSnippet.length > 1500) {
            payloadSnippet = payloadSnippet.substring(0, 1500) + "\n... (truncated)";
        }
    } catch (e) {
        payloadSnippet = "Error stringifying payload";
    }
};

const errorMessage = `🚨 <b>ERROR</b> 🚨

<b>Time:</b> <code>${timestamp}</code>
<b>Message:</b> <u>${error?.message || 'Unknown error'}</u>

<b>Details:</b>
• <b>Node:</b> <code>${source?.name || 'n/a'}</code>
• <b>Type:</b> <code>${source?.type || 'n/a'}</code>
• <b>ID:</b> <code>${source?.id || 'n/a'}</code>
• <b>Attempt:</b> ${source?.count || 1}

<b>Payload Data:</b>
<pre><code>${payloadSnippet}</code></pre>`;

msg.payload = {
    message: errorMessage,
    topic: 'errors'
};

return msg;

const NODE_RED_URL = env.get('NODE_RED_URL') || null;
const TELEGRAM_BOT_TOKEN = env.get('TELEGRAM_BOT_TOKEN') || null;
const TELEGRAM_BASE_URL = env.get('TELEGRAM_BASE_URL') || null;

if (!NODE_RED_URL || !TELEGRAM_BOT_TOKEN || !TELEGRAM_BASE_URL) {
    node.error("Missed data in ENV", msg);
};

const webhookUrl = `${NODE_RED_URL}/api/v1/webhook/telegram`;
msg.url = `${TELEGRAM_BASE_URL}/bot${TELEGRAM_BOT_TOKEN}/setWebhook?url=${webhookUrl}`;
msg.method = 'GET';

return msg;

